using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[CustomEditor(typeof(DungeonDecorationSettings))]public class DungeonDecorationSettingsEditor:Editor {
 [MenuItem("Editor/Decoración y ambientación",false,2025)]static void Open(){var map=DungeonMapSettings.Current;Selection.activeObject=map!=null&&map.decorations!=null?(UnityEngine.Object)map.decorations:DungeonDecorationCatalog.Current;}
 static DungeonMapSettings FindMap(DungeonDecorationSettings settings){foreach(string guid in AssetDatabase.FindAssets("t:DungeonMapSettings")){var map=AssetDatabase.LoadAssetAtPath<DungeonMapSettings>(AssetDatabase.GUIDToAssetPath(guid));if(map.decorations==settings)return map;}return null;}
 public override void OnInspectorGUI(){serializedObject.Update();EditorGUILayout.HelpBox("Decoración separada del gameplay. Semilla fija = misma distribución al recargar. Las zonas sin regla usan densidad global. El catálogo contiene prefabs sin colisiones; automática respeta inicio, NPC, cofres, nodos, puertas y enemigos manuales.",MessageType.Info);DrawDefaultInspector();var settings=(DungeonDecorationSettings)target;if(GUILayout.Button("Guardar configuración"))AssetDatabase.SaveAssetIfDirty(settings);if(Application.isPlaying&&GUILayout.Button("Reconstruir decoración en Play")){foreach(var runtime in UnityEngine.Object.FindObjectsByType<DungeonDecorationRuntime>())if(runtime.map!=null&&runtime.map.decorations==settings)runtime.Rebuild();}var map=FindMap(settings);if(map==null)return;if(GUILayout.Button("Ver mapa en Inspector"))Selection.activeObject=map;
  if(GUILayout.Button("Previsualizar ubicación en SceneView")){DecorationScenePreview.map=map;DecorationScenePreview.Enable();}
  if(GUILayout.Button("Convertir distribución automática a colocaciones editables")){var items=DungeonDecorationPlanner.Build(map);Undo.RecordObject(settings,"Convertir decoración automática");foreach(var p in items)if(!settings.placements.Exists(old=>old.id==p.id))settings.placements.Add(p);settings.automaticEnabled=false;settings.revision++;EditorUtility.SetDirty(settings);AssetDatabase.SaveAssetIfDirty(settings);}
  if(GUILayout.Button("Validar decoraciones")){var messages=new List<string>();var ids=new HashSet<string>();foreach(var p in settings.placements){if(!ids.Add(p.id))messages.Add("ID duplicado "+p.id);var error=DungeonDecorationPlanner.InvalidReason(map,p,settings.Catalog.Find(p.prefabId));if(error!=null)messages.Add(p.id+": "+error);}EditorUtility.DisplayDialog("Decoración",messages.Count==0?"Colocaciones válidas. Prefabs generados sin colisiones.":string.Join("\n",messages.ToArray()),"OK");}
 }
}
[CustomPropertyDrawer(typeof(DecorationZoneRule))]public class DecorationZoneRuleDrawer:PropertyDrawer {
 public override float GetPropertyHeight(SerializedProperty p,GUIContent label){return 4*(EditorGUIUtility.singleLineHeight+3);}
 public override void OnGUI(Rect r,SerializedProperty p,GUIContent label){var settings=p.serializedObject.targetObject as DungeonDecorationSettings;var regions=settings!=null&&settings.regions!=null?settings.regions:DungeonRegionSettings.Current;var names=new List<string>{"Zonas sin asignar"};var ids=new List<string>{"default"};if(regions!=null)foreach(var zone in regions.regions){names.Add(zone.displayName);ids.Add(zone.id);}float h=EditorGUIUtility.singleLineHeight;var id=p.FindPropertyRelative("zoneId");EditorGUI.BeginProperty(r,label,p);int current=ids.IndexOf(id.stringValue);if(current<0){names.Add(id.stringValue);ids.Add(id.stringValue);current=ids.Count-1;}id.stringValue=ids[EditorGUI.Popup(new Rect(r.x,r.y,r.width,h),"Zona",current,names.ToArray())];r.y+=h+3;foreach(var field in new[]{"enabled","density","theme"}){EditorGUI.PropertyField(new Rect(r.x,r.y,r.width,h),p.FindPropertyRelative(field));r.y+=h+3;}EditorGUI.EndProperty();}
}
[CustomPropertyDrawer(typeof(DungeonDecorationPlacement))]public class DecorationPlacementDrawer:PropertyDrawer {
 public override float GetPropertyHeight(SerializedProperty p,GUIContent label){return p.isExpanded?9*(EditorGUIUtility.singleLineHeight+3):EditorGUIUtility.singleLineHeight;}
 public override void OnGUI(Rect r,SerializedProperty p,GUIContent label){float h=EditorGUIUtility.singleLineHeight;var settings=p.serializedObject.targetObject as DungeonDecorationSettings;var catalog=settings!=null?settings.Catalog:DungeonDecorationCatalog.Current;var def=catalog!=null?catalog.Find(p.FindPropertyRelative("prefabId").stringValue):null;p.isExpanded=EditorGUI.Foldout(new Rect(r.x,r.y,r.width,h),p.isExpanded,def!=null?def.displayName:label.text,true);if(!p.isExpanded)return;r.y+=h+3;var names=new List<string>{"Seleccionar"};var ids=new List<string>{""};if(catalog!=null)foreach(var d in catalog.entries){names.Add(d.displayName+" / "+d.mount);ids.Add(d.id);}var prefab=p.FindPropertyRelative("prefabId");prefab.stringValue=ids[EditorGUI.Popup(new Rect(r.x,r.y,r.width,h),"Prefab",Mathf.Max(0,ids.IndexOf(prefab.stringValue)),names.ToArray())];r.y+=h+3;foreach(var key in new[]{"enabled","cell","heading","localOffset","scale","yawOffset","id"}){EditorGUI.PropertyField(new Rect(r.x,r.y,r.width,h),p.FindPropertyRelative(key));r.y+=h+3;}}
}
public static class DecorationScenePreview {
 public static DungeonMapSettings map;static bool enabled;
 public static void Enable(){enabled=true;SceneView.duringSceneGui-=Draw;SceneView.duringSceneGui+=Draw;var view=SceneView.lastActiveSceneView;if(view!=null&&map!=null){float cell=EnemySpaceLayout.Corridor(DungeonVisualSettings.Current,EnemySizeSettings.Current).x;view.Frame(new Bounds(new Vector3(map.rows[0].Length*cell*.5f,0,map.rows.Length*cell*.5f),new Vector3(map.rows[0].Length*cell,4,map.rows.Length*cell)),false);}SceneView.RepaintAll();}
 static void Draw(SceneView view){if(!enabled||map==null||map.decorations==null)return;Handles.color=new Color(.5f,.2f,1,.8f);float size=EnemySpaceLayout.Corridor(DungeonVisualSettings.Current,EnemySizeSettings.Current).x;foreach(var p in DungeonDecorationPlanner.Build(map)){var at=new Vector3(p.cell.x*size,.15f,p.cell.y*size);Handles.DrawWireCube(at,new Vector3(size*.8f,.2f,size*.8f));var def=map.decorations.Catalog.Find(p.prefabId);Handles.Label(at,def.displayName);}Handles.BeginGUI();if(GUI.Button(new Rect(15,15,220,30),"Cerrar previsualización de decoración")){enabled=false;SceneView.duringSceneGui-=Draw;}Handles.EndGUI();}
}
